"use client";

import {
  type FC,
  type ReactElement,
  type ReactNode,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import { slideMarkdownComponents } from "@/lib/markdown/element-defaults";
/**
 * `<Slide>` — view-only primitive that renders markdown + YAML frontmatter
 * into a themed, fixed-aspect surface. Lives in the isolated subpath
 * `@theokit/ui/slide`.
 *
 * See RFC 0002 (`wiki/rfcs/0002-slide.md`).
 *
 * SSR note: initial render returns the section wrapper; the parsed React tree
 * fills in client-side via the useEffect → `parseSlide` chain. Consumers
 * wrapping in Suspense / skeleton can mitigate visible jump.
 *
 * Performance tip: pass a memoized `onValidationError` (via `useCallback`)
 * and a memoized `components` map. Inline arrows recreate on each render
 * and cause re-parses.
 */
import { type ParsedSlide, parseSlide } from "@/components/ui/slide/parse";
import type { SlidePlugin } from "@/components/ui/slide/plugin";
import type { SlideValidationError } from "@/components/ui/slide/schema";
import type { SlideTheme } from "@/components/ui/slide/themes/index";
import { useSlideFit } from "@/components/ui/slide/use-slide-fit";

export type { SlideTheme } from "@/components/ui/slide/themes/index";
export type {
  SlideValidationError,
  SlideValidationErrorCode,
} from "@/components/ui/slide/schema";
export type { SlidePlugin } from "@/components/ui/slide/plugin";

export interface SlideAspectRatio {
  width: number;
  height: number;
}

export interface SlideProps {
  /**
   * Slide markdown. CommonMark + GFM + optional YAML frontmatter delimited
   * by `---`. Top-level horizontal rules (`---` on their own line outside
   * frontmatter) imply a deck split and trigger `MULTIPLE_SLIDES`; only the
   * first slide is rendered.
   *
   * Note: `<figure>`/`<figcaption>` tags are stripped by the default
   * sanitize schema (D8). Use `<img>` directly for captionless images.
   */
  markdown: string;
  /** Theme name. Defaults to `"default"`. */
  theme?: SlideTheme;
  /**
   * Aspect ratio of the logical canvas. Default `"16:9"` → 1280×720.
   * Custom `{ width, height }` accepted; zero/negative/NaN fallback to 16:9.
   */
  aspectRatio?: "16:9" | "4:3" | SlideAspectRatio;
  /** Lower clamp for container-fit scale. Default 0.1. */
  minScale?: number;
  /** Upper clamp for container-fit scale. Default 4. */
  maxScale?: number;
  /** Best-effort callback invoked in useEffect when validation/sanitize emits errors. */
  onValidationError?: (errors: SlideValidationError[]) => void;
  /** Override individual element renderers (passed to hast-util-to-jsx-runtime). */
  // biome-ignore lint/suspicious/noExplicitAny: third-party component override map
  components?: Record<string, FC<any>>;
  /**
   * Rich-content plugins (Tier 2). Each plugin transforms the mdast/hast tree
   * or adds React component overrides. Pass MEMOIZED arrays to avoid re-parses
   * on every render (D15).
   *
   * @example
   *   const plugins = useMemo(() => [emojiPlugin(), shikiPlugin()], []);
   *   <Slide markdown={md} plugins={plugins} />
   */
  plugins?: SlidePlugin[];
  /** Accessible label for the slide. Defaults to `"Slide"`. */
  "aria-label"?: string;
  /** Optional class applied to the outer host element (sizing/positioning hook). */
  className?: string;
}

const ASPECT_PRESETS: Record<"16:9" | "4:3", SlideAspectRatio> = {
  "16:9": { width: 1280, height: 720 },
  "4:3": { width: 960, height: 720 },
};

/**
 * Resolve aspectRatio prop to concrete dimensions. Invalid custom values
 * (zero, negative, non-finite) silently fall back to 16:9 — surfaced via
 * `INVALID_ASPECT_RATIO` error in `onValidationError`. ADR D14.
 */
function resolveCanvas(ar: SlideProps["aspectRatio"]): {
  width: number;
  height: number;
  invalid?: boolean;
} {
  if (!ar || ar === "16:9") return ASPECT_PRESETS["16:9"];
  if (ar === "4:3") return ASPECT_PRESETS["4:3"];
  if (
    ar.width <= 0 ||
    ar.height <= 0 ||
    !Number.isFinite(ar.width) ||
    !Number.isFinite(ar.height)
  ) {
    return { ...ASPECT_PRESETS["16:9"], invalid: true };
  }
  return ar;
}

export const Slide: FC<SlideProps> = ({
  markdown,
  theme = "default",
  aspectRatio = "16:9",
  minScale,
  maxScale,
  onValidationError,
  // #154 — markdown gets this package's defaults unless the consumer decides otherwise. A default
  // and never a merge: a consumer passing `components` is making a decision, and merging ours over
  // theirs would make the default a ceiling instead of a floor.
  components = slideMarkdownComponents,
  plugins,
  className,
  "aria-label": ariaLabel = "Slide",
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvas = useMemo(() => resolveCanvas(aspectRatio), [aspectRatio]);
  const scale = useSlideFit(containerRef, canvas.width, canvas.height, {
    minScale,
    maxScale,
  });

  const [parsed, setParsed] = useState<ParsedSlide | null>(null);

  // Surface INVALID_ASPECT_RATIO immediately when the prop is invalid.
  // Independent of markdown parsing so consumers see the signal even with
  // an empty markdown payload.
  useEffect(() => {
    if (canvas.invalid && onValidationError) {
      onValidationError([
        {
          code: "INVALID_ASPECT_RATIO",
          path: ["aspectRatio"],
          message:
            "aspectRatio width/height must be positive finite numbers; falling back to 16:9.",
          got: aspectRatio,
        },
      ]);
    }
  }, [canvas.invalid, onValidationError, aspectRatio]);

  // EC-7 / version counter — prevents older parses from overwriting newer
  // ones on rapid prop changes.
  const versionRef = useRef(0);
  useEffect(() => {
    const myVersion = ++versionRef.current;
    let cancelled = false;
    parseSlide(markdown, { components, plugins }).then(
      (result) => {
        if (cancelled || myVersion !== versionRef.current) return;
        setParsed(result);
        if (result.errors.length > 0 && onValidationError) {
          onValidationError(result.errors);
        }
      },
      (err: unknown) => {
        // Defensive: parseSlide promises to never throw, but if a runtime
        // failure escapes (e.g. peer-dep missing), surface a synthetic error
        // and keep the slide visible with empty body.
        if (cancelled || myVersion !== versionRef.current) return;
        if (onValidationError) {
          onValidationError([
            {
              code: "INVALID_FRONTMATTER",
              path: [],
              message: err instanceof Error ? err.message : "parseSlide rejected.",
            },
          ]);
        }
        setParsed({
          frontmatter: {},
          tree: emptyFragment(),
          errors: [],
          truncated: false,
        });
      },
    );
    return () => {
      cancelled = true;
    };
  }, [markdown, components, plugins, onValidationError]);

  const treeNode: ReactNode = parsed?.tree ?? null;
  const slideThemeAttr: SlideTheme = theme;

  // Tier 1 — frontmatter-driven attributes & overlays.
  const fm = parsed?.frontmatter ?? {};
  const layout = fm.layout;
  // Background precedence: explicit frontmatter > Marpit ![bg](url) (D18 / EC-5).
  const bgUrl = fm.backgroundImage ?? parsed?.extractedBackground?.url;
  const bgModifier = parsed?.extractedBackground?.modifier;
  const bgGradient = fm.backgroundGradient;
  const headerText = fm.header;
  const footerText = fm.footer;
  const paginateValue = fm.paginate;
  const showPaginate = paginateValue === true;

  // Background style: gradient > image > inherited.
  const backgroundImageStyle: string | undefined = bgGradient
    ? bgGradient
    : bgUrl
      ? `url("${bgUrl}")`
      : undefined;

  return (
    <div
      data-slot="slide"
      ref={containerRef}
      className={["theo-slide-host", className].filter(Boolean).join(" ")}
      data-theo-slide-host
      style={{
        position: "relative",
        overflow: "hidden",
        width: "100%",
        height: "100%",
      }}
    >
      {/*
        Section is taken out of normal flow with position:absolute so its
        1280×720 layout box doesn't inflate the host. `translate(-50%, -50%)`
        anchors the section's center to the host's center; the scale applies
        relative to that same origin. Mirrors Reveal.js transformSlides()
        (see `wiki/engines/slide-authoring-guide.md`).
      */}
      <section
        aria-roledescription="slide"
        aria-label={ariaLabel}
        className="theo-slide"
        data-theo-slide-theme={slideThemeAttr}
        data-theo-slide-layout={layout ?? "default"}
        data-theo-slide-bg-modifier={bgModifier}
        style={{
          position: "absolute",
          top: "50%",
          left: "50%",
          width: canvas.width,
          height: canvas.height,
          transform: `translate(-50%, -50%) scale(${scale})`,
          transformOrigin: "center",
          padding: "var(--theo-slide-padding, 64px)",
          color: "inherit",
          // Background fills the canvas. When neither image nor gradient is set,
          // the slide inherits the parent surface (same pattern as Whiteboard).
          background: "transparent",
          // Only set backgroundImage + ancillary props when one is provided —
          // otherwise the shorthand `background: transparent` is preserved as-is
          // (important for the inherit-from-parent guarantee).
          ...(backgroundImageStyle
            ? {
                backgroundImage: backgroundImageStyle,
                backgroundSize: bgModifier === "fit" ? "contain" : "cover",
                backgroundPosition: "center",
                backgroundRepeat: "no-repeat",
              }
            : {}),
          fontFamily:
            "var(--theo-slide-font-family, system-ui, -apple-system, 'Segoe UI', sans-serif)",
          fontSize: "var(--theo-slide-font-base, 28px)",
          lineHeight: 1.5,
          boxSizing: "border-box",
          overflow: "hidden",
        }}
      >
        {headerText ? (
          <div className="theo-slide-header" aria-hidden="true">
            {headerText}
          </div>
        ) : null}
        {treeNode}
        {footerText ? (
          <div className="theo-slide-footer" aria-hidden="true">
            {footerText}
          </div>
        ) : null}
        {showPaginate ? (
          <div className="theo-slide-paginate" aria-hidden="true">
            1
          </div>
        ) : null}
      </section>
    </div>
  );
};

/** Empty React fragment placeholder used when parseSlide fails fatally. */
function emptyFragment(): ReactElement {
  // Cheap fallback that does not require importing Fragment from react/jsx-runtime.
  // Using a real element keeps the type as ReactElement (not ReactNode).
  return { type: "span", props: { children: null }, key: null } as unknown as ReactElement;
}

import type { ComponentProps, JSX } from "react";

import { safeHref } from "@/lib/safe-href";

/**
 * The defaults a slide's markdown gets when the consumer passes no `components` map.
 *
 * usetheokit/theokit-ui#154: `<Slide components={...}>` has been public API since the primitive
 * shipped and `parse.ts` passes whatever it gets straight to `toJsxRuntime` — but nothing supplied a
 * default, so `![]()` and `[]()` rendered as bare `<img>` and `<a>` with none of the defaults this
 * package applies wherever it renders one itself.
 *
 * ## What this is NOT
 *
 * Not a security fix. The issue framed the link half that way — a `target="_blank"` link without
 * `rel="noopener"` hands the opened page a live `window.opener` — and the premise does not hold:
 * the sanitize schema strips `target`, measured on `hast-util-sanitize`'s own output. A markdown
 * link cannot open a new browsing context at all, so the opener is never handed to anything.
 *
 * `rel` is here as DEFENCE IN DEPTH, and the distinction matters for whoever reads this next:
 * `getSlideSanitizeSchema` unions plugin-declared attributes onto the baseline, so a plugin
 * declaring `a: ["target"]` reopens the door. With this default the protection travels with the
 * anchor instead of depending on nobody ever widening the schema.
 *
 * ## Why a plain element and not the package's own components
 *
 * There is no `Image` component in this package — measured, not assumed. Mapping markdown onto a
 * component that does not exist is the kind of plan that reads well and cannot ship. What markdown
 * was missing is the ATTRIBUTES, and those are what this supplies.
 */

/** A link's destination is another origin, so an opener reference would cross a boundary. */
function isExternal(href: string | undefined): boolean {
  if (href === undefined || href === "") return false;
  // Fragment and relative links stay in this document. A default that fired on `#section` would be
  // noise, and a noisy default is one consumers replace wholesale rather than extend.
  if (href.startsWith("#") || href.startsWith("/") || href.startsWith("./")) return false;
  return /^[a-z][a-z0-9+.-]*:/i.test(href);
}

/**
 * `Record<string, unknown>` on the surface, for the reason `parse.ts` records: the JSX-runtime types
 * come from an OPTIONAL peer, and naming them here would make that peer a hard requirement for every
 * consumer — including the ones who never render markdown.
 */
export const slideMarkdownComponents: Record<
  string,
  ((props: Record<string, unknown>) => JSX.Element) | undefined
> = {
  a(props) {
    const { href, children, ...rest } = props as ComponentProps<"a"> & {
      children?: React.ReactNode;
    };
    // `safeHref` rather than a second protocol check: it already refuses `javascript:` and `data:`
    // and is what `loadThemeFonts` trusts for the same question. One answer, one place.
    const safe = typeof href === "string" ? safeHref(href) : undefined;
    const external = isExternal(safe);
    return (
      <a {...rest} href={safe} rel={external ? "noopener noreferrer" : undefined}>
        {children}
      </a>
    );
  },

  img(props) {
    const { src, alt, ...rest } = props as ComponentProps<"img">;
    const safe = typeof src === "string" ? safeHref(src) : undefined;
    return (
      <img
        {...rest}
        src={safe}
        // `alt=""` and no alt are different claims to a screen reader: the first says "skip me", the
        // second makes it read the URL aloud. `![](x.png)` is an author saying there is nothing to
        // announce, so the empty string is the honest translation of it.
        alt={typeof alt === "string" ? alt : ""}
        loading="lazy"
        decoding="async"
      />
    );
  },
};

import type { Root as HastRoot } from "hast";
/**
 * Markdown → React tree pipeline for the Slide primitive.
 *
 *   parseSlide(markdown)
 *     ├─ validateSlide(markdown) → { frontmatter, body, errors? }
 *     ├─ parseBody(body)        → mdast Root (micromark + GFM)
 *     ├─ mdastToHast(mdastTree) → hast Root (allowDangerousHtml: false)
 *     ├─ sanitizeHast(hastTree) → hast Root + BANNED_TAG diff (ADR D13)
 *     └─ hastToReact(hastTree)  → React tree (jsx-runtime, no innerHTML)
 *
 * Every transform is composed of lazy-imported peer-deps so the slide bundle
 * stays under budget and never vendors the markdown stack into the barrel
 * (ADR D2 / D3 of the slide plan).
 */
import type { Root as MdastRoot } from "mdast";
import type { ReactElement } from "react";
import { detectAlerts } from "@/components/ui/slide/alerts";
import { extractMarpitBackgrounds } from "@/components/ui/slide/marpit-bg";
import { type MergedSanitizeExtensions, type SlidePlugin, composePlugins } from "@/components/ui/slide/plugin";
import { collectTagCounts, getSlideSanitizeSchema } from "@/components/ui/slide/sanitize";
import { type SlideFrontmatter, type SlideValidationError, sanitizeBgUrl } from "@/components/ui/slide/schema";
import { validateSlide } from "@/components/ui/slide/validate";

export interface ParseSlideOptions {
  /** Override individual element renderers (passed to hast-util-to-jsx-runtime). */
  components?: Record<string, unknown>;
  /** Rich-content plugins (Tier 2). Order matters — D13 / RFC 0004. */
  plugins?: SlidePlugin[];
}

export interface ExtractedBackground {
  /** Sanitized URL (http/https only). */
  url: string;
  /** Optional Marpit modifier: `cover` | `fit` | `left` | `right`. */
  modifier?: "cover" | "fit" | "left" | "right";
}

export interface ParsedSlide {
  frontmatter: SlideFrontmatter;
  /** React element renderable as the body of a slide. Always defined (may be empty Fragment). */
  tree: ReactElement;
  /** Validation + sanitize errors collected during parsing. Empty on success. */
  errors: SlideValidationError[];
  /** True when the input contained a top-level thematic break and only the first slide was rendered. */
  truncated: boolean;
  /**
   * Background image extracted from Marpit `![bg](url)` syntax (D18 / EC-5).
   * Precedence: `frontmatter.backgroundImage` > `extractedBackground.url`.
   */
  extractedBackground?: ExtractedBackground;
}

export async function parseBody(body: string): Promise<MdastRoot> {
  const [{ fromMarkdown }, { gfmFromMarkdown }, { gfm }] = await Promise.all([
    import("mdast-util-from-markdown"),
    import("mdast-util-gfm"),
    import("micromark-extension-gfm"),
  ]);
  return fromMarkdown(body, {
    extensions: [gfm()],
    mdastExtensions: [gfmFromMarkdown()],
  });
}

export async function mdastToHast(tree: MdastRoot): Promise<HastRoot> {
  const { toHast } = await import("mdast-util-to-hast");
  const hast = toHast(tree, { allowDangerousHtml: false });
  if (!hast || hast.type !== "root") {
    return { type: "root", children: hast ? [hast] : [] } as HastRoot;
  }
  return hast as HastRoot;
}

export async function sanitizeHast(
  tree: HastRoot,
  extensions?: MergedSanitizeExtensions,
): Promise<{ tree: HastRoot; bannedTags: string[] }> {
  const schema = await getSlideSanitizeSchema(extensions);
  const { sanitize } = await import("hast-util-sanitize");
  const preCount = collectTagCounts(tree);
  const safe = sanitize(tree, schema);
  const safeRoot: HastRoot =
    safe.type === "root" ? (safe as HastRoot) : ({ type: "root", children: [safe] } as HastRoot);
  const postCount = collectTagCounts(safeRoot);
  const bannedTags: string[] = [];
  for (const [tag, before] of preCount) {
    const after = postCount.get(tag) ?? 0;
    if (after < before) {
      // Push once per stripped tag name; agents can self-correct from this signal.
      bannedTags.push(tag);
    }
  }
  return { tree: safeRoot, bannedTags };
}

export async function hastToReact(
  tree: HastRoot,
  components?: Record<string, unknown>,
): Promise<ReactElement> {
  const { Fragment, jsx, jsxs } = await import("react/jsx-runtime");
  const { toJsxRuntime } = await import("hast-util-to-jsx-runtime");
  return toJsxRuntime(tree, {
    Fragment,
    jsx,
    jsxs,
    // `components` is `Record<string, unknown>` on our public surface and
    // `Partial<Components>` here. It cannot be typed as the latter: `hast-util-to-jsx-runtime`
    // is an OPTIONAL peer, so naming its types in our published API would make them a hard
    // requirement for every consumer, including the ones who never render markdown. Under
    // React 18's types the two were structurally compatible and this went unnoticed; React
    // 19 tightened the value union and they no longer are. The cast is the adapter at that
    // boundary — the runtime contract is unchanged, and toJsxRuntime validates what it gets.
    components: components as Parameters<typeof toJsxRuntime>[1]["components"],
  }) as ReactElement;
}

/**
 * Public entry point. Validates → parses → sanitizes → returns a React tree.
 *
 * Never throws on input. Errors (validation, BANNED_TAG) are collected into
 * `errors[]` so callers can show them via `onValidationError`.
 */
export async function parseSlide(
  markdown: string,
  opts: ParseSlideOptions = {},
): Promise<ParsedSlide> {
  const errors: SlideValidationError[] = [];
  let frontmatter: SlideFrontmatter = {};
  let body = markdown;
  let truncated = false;

  const validation = await validateSlide(markdown);
  if (validation.ok) {
    frontmatter = validation.input.frontmatter;
    body = validation.input.body;
    errors.push(...validation.errors);
    truncated = validation.errors.some((e) => e.code === "MULTIPLE_SLIDES");
  } else {
    errors.push(...validation.errors);
    // Best-effort recovery: render the body as if frontmatter was absent.
    // This preserves "never throw, always render something" contract.
    body = markdown;
  }

  const compose = composePlugins(opts.plugins ?? []);

  const rawMdast = await parseBody(body);
  // Tier 1 — GFM alerts (D3): in-tree post-process, no plugin needed.
  // Runs BEFORE plugin mdastTransforms so plugins observing the tree see the
  // normalized aside shape (consistent with how `> [!NOTE]` is treated as
  // native GFM by consumers).
  detectAlerts(rawMdast);
  // Tier 1 — Marpit ![bg](url) (D18 / EC-5): extract before plugins run so the
  // tree handed to plugins is free of bg directives.
  const { tree: mdastNoBg, background: marpitBg } = extractMarpitBackgrounds(rawMdast);
  let extractedBackground: ExtractedBackground | undefined;
  if (marpitBg) {
    const safeUrl = sanitizeBgUrl(marpitBg.url);
    if (safeUrl) {
      extractedBackground = { url: safeUrl, modifier: marpitBg.modifier };
    } else {
      errors.push({
        code: "MARPIT_BG_UNSAFE_URL",
        path: [],
        message: "Marpit ![bg](url) rejected: unsafe scheme or malformed URL.",
        got: marpitBg.url.slice(0, 80),
      });
    }
  }
  const transformedMdast = await compose.runMdast(mdastNoBg, errors);
  const rawHast = await mdastToHast(transformedMdast);
  const transformedHast = await compose.runHast(rawHast, errors);

  // D17 / EC-3: merge plugin sanitize-schema extensions with defaultSchema so
  // plugins emitting non-default tags (Shiki spans, KaTeX MathML, Mermaid SVG)
  // survive the security barrier. Sanitize ALWAYS runs.
  const sanitizeExtensions = compose.mergedSanitizeExtensions();
  const { tree: safeTree, bannedTags } = await sanitizeHast(transformedHast, sanitizeExtensions);
  for (const tag of bannedTags) {
    errors.push({
      code: "BANNED_TAG",
      path: ["body"],
      message: `Tag <${tag}> was stripped by the slide sanitizer.`,
      got: tag,
    });
  }

  // D2 / D13: plugin component overrides merge on top of consumer's components;
  // plugin definitions win on conflict (last-write-wins in mergedComponents).
  const mergedComponents = {
    ...(opts.components ?? {}),
    ...compose.mergedComponents(),
  };
  const tree = await hastToReact(safeTree, mergedComponents);

  return { frontmatter, tree, errors, truncated, extractedBackground };
}

import { extractFrontmatter } from "@/components/ui/slide/frontmatter";
/**
 * Async validator for slide markdown input.
 *
 * Returns `Promise<ValidationResult>` (ADR D11 — sync impossible because
 * `yaml` and `mdast-util-from-markdown` are lazy-imported peer-deps).
 *
 * Pipeline:
 *   1. Strip BOM + extract frontmatter (`frontmatter.ts`).
 *   2. Reject `FRONTMATTER_TOO_LARGE` early if raw > 10 KB (ADR D14).
 *   3. Parse YAML in safe mode → validate against `slideFrontmatter` (Zod).
 *   4. Validate body length → emit `CONTENT_TOO_LARGE` if > 50 KB.
 *   5. Detect multi-slide via mdast `thematicBreak` walk (ADR D12) — not
 *      a regex, so `---` inside fenced code blocks does not false-positive.
 *   6. Return `{ ok, input, errors[] }`.
 *
 * Errors are structured so an LLM can self-correct from the callback.
 */
import {
  type SlideFrontmatter,
  type SlideInput,
  type SlideValidationError,
  slideFrontmatter,
} from "@/components/ui/slide/schema";

export type ValidationResult =
  | { ok: true; input: SlideInput; errors: SlideValidationError[] }
  | { ok: false; errors: SlideValidationError[] };

interface ZodLikeIssue {
  path: ReadonlyArray<string | number>;
  message: string;
  code: string;
  received?: unknown;
}

const MAX_BODY = 50_000;

function valueAtPath(input: unknown, path: ReadonlyArray<string | number>): unknown {
  let cursor: unknown = input;
  for (const segment of path) {
    if (cursor === null || typeof cursor !== "object") return undefined;
    cursor = (cursor as Record<string | number, unknown>)[segment];
  }
  return cursor;
}

function formatZodIssue(
  issue: ZodLikeIssue,
  input: unknown,
  pathPrefix: (string | number)[],
): SlideValidationError {
  const error: SlideValidationError = {
    path: [...pathPrefix, ...issue.path],
    message: issue.message,
    code: "INVALID_FRONTMATTER",
  };
  if ("received" in issue && issue.received !== undefined) {
    error.got = issue.received;
  } else if (issue.path.length > 0) {
    const value = valueAtPath(input, issue.path);
    if (value !== undefined) error.got = value;
  }
  return error;
}

async function detectMultiSlide(body: string): Promise<{
  multi: boolean;
  firstSlideBody: string;
}> {
  // mdast-based — regex would false-positive on `---` inside fenced code blocks.
  // Cost: one extra parse. Cheap; would be parsed again in `parse.ts` anyway.
  const { fromMarkdown } = await import("mdast-util-from-markdown");
  const tree = fromMarkdown(body);
  const hrIdx = tree.children.findIndex((n) => n.type === "thematicBreak");
  if (hrIdx === -1) {
    return { multi: false, firstSlideBody: body };
  }
  const firstHr = tree.children[hrIdx];
  const offset = firstHr?.position?.start.offset;
  if (typeof offset !== "number") {
    return { multi: true, firstSlideBody: body };
  }
  return { multi: true, firstSlideBody: body.slice(0, offset) };
}

/**
 * Validate the markdown input. Returns errors structured for LLM self-correction.
 *
 * Async because frontmatter YAML parsing and mdast multi-slide detection both
 * use lazy-imported peer-deps (yaml + mdast-util-from-markdown).
 */
export async function validateSlide(markdown: string): Promise<ValidationResult> {
  const errors: SlideValidationError[] = [];
  const extracted = extractFrontmatter(markdown);

  if (extracted.tooLarge) {
    errors.push({
      code: "FRONTMATTER_TOO_LARGE",
      path: [],
      message: `Raw frontmatter exceeds ${10_240} bytes.`,
      got: extracted.rawFrontmatter?.length,
    });
    return { ok: false, errors };
  }

  let frontmatter: SlideFrontmatter = {};
  if (extracted.rawFrontmatter !== null) {
    let parsed: unknown;
    try {
      const yaml = await import("yaml");
      parsed = yaml.parse(extracted.rawFrontmatter);
    } catch (e) {
      errors.push({
        code: "INVALID_FRONTMATTER",
        path: [],
        message: e instanceof Error ? e.message : "YAML parse failed.",
        got: extracted.rawFrontmatter,
      });
      return { ok: false, errors };
    }
    if (parsed === null || parsed === undefined) {
      // empty frontmatter — treat as {}
      frontmatter = {};
    } else if (typeof parsed !== "object" || Array.isArray(parsed)) {
      errors.push({
        code: "INVALID_FRONTMATTER",
        path: [],
        message: "Frontmatter must be a YAML mapping (object).",
        got: parsed,
      });
      return { ok: false, errors };
    } else {
      const result = slideFrontmatter.safeParse(parsed);
      if (!result.success) {
        for (const issue of result.error.issues) {
          errors.push(formatZodIssue(issue as unknown as ZodLikeIssue, parsed, []));
        }
        return { ok: false, errors };
      }
      frontmatter = result.data;
    }
  }

  let body = extracted.body;

  if (body.length > MAX_BODY) {
    errors.push({
      code: "CONTENT_TOO_LARGE",
      path: ["body"],
      message: `Body exceeds ${MAX_BODY} characters.`,
      got: body.length,
    });
    return { ok: false, errors };
  }

  const multi = await detectMultiSlide(body);
  if (multi.multi) {
    body = multi.firstSlideBody;
    errors.push({
      code: "MULTIPLE_SLIDES",
      path: ["body"],
      message:
        "Input contains a top-level thematic break (---). <Slide> renders single-slide markdown only. Only the first slide was rendered.",
    });
  }

  return { ok: true, input: { frontmatter, body }, errors };
}

/**
 * Sanitize schema for slide body hast trees.
 *
 * ADR D8: `defaultSchema` from `hast-util-sanitize` is used WITHOUT extensions
 * in v0.1. The default schema:
 *   - Strips `<script>`, `<iframe>`, `<object>`, `<embed>`, `<form>`, `<input>`,
 *     `<style>`, `<link>` and other dangerous tags.
 *   - Keeps `clobberPrefix: "user-content-"` so user-supplied IDs cannot
 *     clobber DOM lookups.
 *   - Allows the standard CommonMark + GFM safe subset (h1-h6, p, ul, ol, li,
 *     blockquote, code, pre, a[href], img[src/alt], table family, em, strong,
 *     del, br, hr, etc.).
 *
 * A `looseSlideSanitizeSchema` (with `figure`/`figcaption`) is an explicit
 * opt-in for v0.2 — gated by security review.
 */
import type { Element, Root } from "hast";
import type { MergedSanitizeExtensions } from "@/components/ui/slide/plugin";

let cachedBuiltSchema: import("hast-util-sanitize").Schema | undefined;

/**
 * Tier 1 built-in extensions to the default sanitize schema. These cover the
 * tags emitted by built-in Slide features (alerts in `aside`, layout / header
 * / footer / paginate metadata attributes on the outer section wrapper). They
 * are NOT plugin-declared because they ship with the Slide primitive.
 *
 * Note: layout / header / footer / paginate are applied at the React component
 * level (outside the hast tree), so their attributes don't need sanitize rules.
 * Only `aside` (alerts) ends up in the hast.
 */
const TIER_1_TAG_NAMES: string[] = ["aside"];
const TIER_1_ATTRIBUTES: Record<string, string[]> = {
  aside: ["className", "data-theo-slide-alert-type"],
  "*": ["className"],
};

/**
 * Lazy accessor for the sanitize schema.
 *
 * Always merges `defaultSchema` with the Tier 1 baseline (aside + className).
 * When `extensions` is provided, plugin-declared tag names + attributes are
 * unioned on top (D17 / EC-3). Plugins NEVER bypass sanitize — they declare
 * what they need via `sanitizeSchemaExtension`.
 *
 * Implementation notes:
 *   - The baseline schema (default + Tier 1) is cached.
 *   - Plugin-merged schemas are NOT cached (depends on combination).
 */
export async function getSlideSanitizeSchema(
  extensions?: MergedSanitizeExtensions,
): Promise<import("hast-util-sanitize").Schema> {
  const baseline = await getBaselineSchema();
  if (
    !extensions ||
    (extensions.tagNames.length === 0 && Object.keys(extensions.attributes).length === 0)
  ) {
    return baseline;
  }
  return mergeSchema(baseline, extensions);
}

async function getBaselineSchema(): Promise<import("hast-util-sanitize").Schema> {
  if (cachedBuiltSchema) return cachedBuiltSchema;
  const { defaultSchema } = await import("hast-util-sanitize");
  cachedBuiltSchema = mergeSchema(defaultSchema, {
    tagNames: TIER_1_TAG_NAMES,
    attributes: TIER_1_ATTRIBUTES,
  });
  return cachedBuiltSchema;
}

function mergeSchema(
  base: import("hast-util-sanitize").Schema,
  extensions: MergedSanitizeExtensions,
): import("hast-util-sanitize").Schema {
  // Merge tag names (deduplicated set).
  const baseTagNames = (base.tagNames ?? []) as string[];
  const tagSet = new Set<string>(baseTagNames);
  for (const t of extensions.tagNames) tagSet.add(t);
  // Merge attributes per tag.
  const baseAttrs = (base.attributes ?? {}) as Record<string, unknown[]>;
  const mergedAttrs: Record<string, unknown[]> = { ...baseAttrs };
  for (const [tag, attrs] of Object.entries(extensions.attributes)) {
    const baseline = (mergedAttrs[tag] ?? []) as unknown[];
    const seen = new Set<string>();
    const combined: unknown[] = [];
    for (const a of baseline) {
      const key = typeof a === "string" ? a : JSON.stringify(a);
      if (!seen.has(key)) {
        seen.add(key);
        combined.push(a);
      }
    }
    for (const a of attrs) {
      if (!seen.has(a)) {
        seen.add(a);
        combined.push(a);
      }
    }
    mergedAttrs[tag] = combined;
  }
  return {
    ...base,
    tagNames: Array.from(tagSet),
    attributes: mergedAttrs,
  } as import("hast-util-sanitize").Schema;
}

/** Count elements by tagName in a hast tree. Used for BANNED_TAG detection (ADR D13). */
export function collectTagCounts(tree: Root | Element): Map<string, number> {
  const counts = new Map<string, number>();
  const walk = (node: Root | Element | { type: string; children?: unknown[] }): void => {
    if (node.type === "element") {
      const tag = (node as Element).tagName;
      counts.set(tag, (counts.get(tag) ?? 0) + 1);
    }
    const children = (node as { children?: unknown[] }).children;
    if (Array.isArray(children)) {
      for (const child of children) {
        if (child && typeof child === "object" && "type" in child) {
          walk(child as Root | Element);
        }
      }
    }
  };
  walk(tree);
  return counts;
}

/**
 * Zod schema for the Slide YAML frontmatter (`SlideFrontmatter`) and the
 * composed `SlideInput` (frontmatter + body).
 *
 * Design (see RFC 0002 and the plan in
 * `wiki/rfcs/0002-slide.md`, ADRs D4 / D14):
 *
 * - **`.strict()`** on frontmatter — unknown keys produce `INVALID_FRONTMATTER`
 *   with a precise path, so an LLM can self-correct.
 * - Numeric values are `.finite()` to reject `NaN` / `Infinity`. (Currently no
 *   numeric directives ship; keep the helper for future fields.)
 * - String values capped to defensible sizes to reject DoS-shaped inputs.
 * - `body` capped to 50 KB (≈30 slides' worth of text) per the sanity rule.
 * - `theme` is the canonical enum of built-in themes. Custom themes are not
 *   registered via frontmatter in v0.1 — caller wraps `<Slide>` with their
 *   own CSS overrides.
 */
import { z } from "zod";

/** Built-in slide themes. Adding a theme means landing a CSS file in `themes/`. */
export const slideTheme = z.enum(["default", "violet-forge"]);
export type SlideTheme = z.infer<typeof slideTheme>;

/** Built-in slide layouts (rich-content plan T2.1). */
export const slideLayout = z.enum([
  "default",
  "title",
  "two-column",
  "image-right",
  "image-left",
  "code-output",
  "section",
]);
export type SlideLayout = z.infer<typeof slideLayout>;

const cssColor = z.string().max(64);
// BCP-47 language tag — loose validation, just sanity to reject obvious junk.
const langTag = z
  .string()
  .regex(/^[a-z]{2,3}(-[A-Za-z0-9]{2,8})*$/, "Expected BCP-47 language tag")
  .max(35);

// EC-7 / rich-content T3.1 helpers.
const SAFE_URL_SCHEMES = ["http://", "https://"];

/**
 * Sanitize a `backgroundImage` URL.
 *
 * Allowed: `http(s)://...` URLs (validated via `URL` constructor).
 * Rejected: `javascript:`, `vbscript:`, all `data:` URLs (EC-7 — perf + DoS).
 * Accepts a bare URL or a `url(...)` wrapper. Returns the unwrapped URL on
 * success, `null` on rejection.
 */
export function sanitizeBgUrl(input: string): string | null {
  try {
    const trimmed = input.trim();
    const url = trimmed.startsWith("url(")
      ? trimmed.replace(/^url\(\s*['"]?/, "").replace(/['"]?\s*\)$/, "")
      : trimmed;
    const lower = url.toLowerCase();
    if (lower.startsWith("javascript:") || lower.startsWith("vbscript:")) return null;
    // EC-7: reject ALL data: URLs (including data:image/*) — slides inflate the
    // markdown payload and shifts loading cost. Consumer should host images.
    if (lower.startsWith("data:")) return null;
    if (!SAFE_URL_SCHEMES.some((s) => lower.startsWith(s))) return null;
    new URL(url); // throws on malformed
    return url;
  } catch {
    return null;
  }
}

/** YAML frontmatter accepted by `<Slide>`. */
export const slideFrontmatter = z
  .object({
    theme: slideTheme.optional(),
    /** Rich-content T2: built-in layout (CSS grid). */
    layout: slideLayout.optional(),
    /** Rich-content T3: background URL (sanitized: http(s) only). */
    backgroundImage: z
      .string()
      .max(500_000)
      .transform((v) => {
        if (!v) return undefined;
        const sanitized = sanitizeBgUrl(v);
        return sanitized ?? undefined;
      })
      .optional(),
    /** Rich-content T3: CSS gradient string (validated by prefix). */
    backgroundGradient: z
      .string()
      .max(500)
      .regex(
        /^(linear|radial|conic)-gradient\(/i,
        "Must start with linear-/radial-/conic-gradient(",
      )
      .optional(),
    /** Rich-content T5: header overlay text (plain, ≤ 200 chars). */
    header: z.string().max(200).optional(),
    /** Rich-content T5: footer overlay text (plain, ≤ 200 chars). */
    footer: z.string().max(200).optional(),
    /** Rich-content T5: pagination — `true` shows page number, `"skip"` hides. */
    paginate: z.union([z.boolean(), z.literal("skip"), z.literal("hold")]).optional(),
    lang: langTag.optional(),
    color: cssColor.optional(),
    backgroundColor: cssColor.optional(),
  })
  .strict();
export type SlideFrontmatter = z.infer<typeof slideFrontmatter>;

/** Composed input: validated frontmatter object + raw markdown body string. */
export const slideInput = z.object({
  frontmatter: slideFrontmatter,
  body: z.string().max(50_000),
});
export type SlideInput = z.infer<typeof slideInput>;

/** Discrete validation-error codes — kept centralized so consumers can pattern-match safely. */
export type SlideValidationErrorCode =
  | "INVALID_FRONTMATTER"
  | "FRONTMATTER_TOO_LARGE"
  | "MULTIPLE_SLIDES"
  | "CONTENT_TOO_LARGE"
  | "BANNED_TAG"
  | "BANNED_ATTRIBUTE"
  | "INVALID_ASPECT_RATIO"
  // Rich-content plan (Tier 1 + Tier 2 plugins):
  | "PLUGIN_ERROR" // D16: a plugin's mdast/hast transform threw — pipeline continued
  | "PLUGIN_PEER_DEP_MISSING" // EC-2: dynamic import of a plugin's peer-dep failed
  | "MARPIT_BG_UNSAFE_URL"; // D18/EC-5: Marpit ![bg](url) rejected by URL sanitizer

export interface SlideValidationError {
  /** Path inside the input (frontmatter key, ['body'], or []). */
  path: (string | number)[];
  /** Human-readable explanation. */
  message: string;
  /** Discriminator for consumers. */
  code: SlideValidationErrorCode;
  /** Offending value when extractable from Zod's `received` or by walking the input. */
  got?: unknown;
}

/**
 * Lightweight, dependency-free extractor that separates YAML frontmatter from
 * the markdown body.
 *
 * Strips a leading BOM (`﻿`) before matching the regex — common when
 * markdown is pasted from Word/Notion. See plan ADR D14 and edge-case EC-4.
 *
 * Returns `{ rawFrontmatter, body, tooLarge? }`:
 *   - `rawFrontmatter`: the YAML string between the two `---` delimiters, or
 *     `null` if no frontmatter is present.
 *   - `body`: the markdown after the closing `---\n` (or the full input when
 *     no frontmatter).
 *   - `tooLarge`: `true` if `rawFrontmatter` exceeds `MAX_RAW_FRONTMATTER`
 *     bytes — the caller turns this into `FRONTMATTER_TOO_LARGE`.
 */

/** Maximum size of the raw frontmatter string before YAML parsing. 10 KB cap. */
export const MAX_RAW_FRONTMATTER = 10_240;

const FRONTMATTER_RE = /^---\r?\n([\s\S]*?)\r?\n---\r?\n([\s\S]*)$/;
const BOM = "﻿";

export interface ExtractFrontmatterResult {
  rawFrontmatter: string | null;
  body: string;
  tooLarge?: boolean;
}

export function extractFrontmatter(md: string): ExtractFrontmatterResult {
  const normalized = md.startsWith(BOM) ? md.slice(1) : md;
  const match = FRONTMATTER_RE.exec(normalized);
  if (!match) {
    return { rawFrontmatter: null, body: normalized };
  }
  const raw = match[1] ?? "";
  const body = match[2] ?? "";
  if (raw.length > MAX_RAW_FRONTMATTER) {
    return { rawFrontmatter: raw, body, tooLarge: true };
  }
  return { rawFrontmatter: raw, body };
}

/**
 * GFM alerts post-processor — converts `> [!NOTE]` blockquotes into
 * `<aside class="theo-slide-alert" data-theo-slide-alert-type="...">` (ADR D3 of
 * the slide-rich-content plan).
 *
 * GitHub Flavored Markdown introduced this convention in 2023 for callouts.
 * `remark-gfm` (already in our dep tree) parses the blockquote but does NOT
 * distinguish alerts from regular blockquotes. We post-process the mdast tree
 * to detect the canonical marker and annotate with `hName` + `hProperties` so
 * `mdast-util-to-hast` emits the desired hast element.
 *
 * Five tag families are supported, mirroring GitHub:
 *   - NOTE      (info / blue)
 *   - TIP       (success / green)
 *   - IMPORTANT (purple)
 *   - WARNING   (yellow)
 *   - CAUTION   (red)
 *
 * Case-insensitive. Marker is stripped from the rendered text. Regular
 * blockquotes (without `[!TYPE]` prefix) are left untouched.
 */
import type { Blockquote, Paragraph, Root, Text } from "mdast";

/** Canonical alert types — used by CSS via `data-theo-slide-alert-type="..."`. */
export const ALERT_TYPES = ["note", "tip", "important", "warning", "caution"] as const;
export type AlertType = (typeof ALERT_TYPES)[number];

const ALERT_RE = /^\[!(NOTE|TIP|IMPORTANT|WARNING|CAUTION)\][ \t]*(?:\r?\n|$)/i;

/**
 * Walk a mdast tree and mutate any blockquote that opens with `[!TYPE]` into
 * an `<aside>` annotation. Mutation is in-place to keep the pipeline allocation
 * profile flat; the same tree is returned for chainability.
 */
export function detectAlerts(tree: Root): Root {
  for (const node of tree.children) {
    if (node.type !== "blockquote") continue;
    transformIfAlert(node);
  }
  return tree;
}

function transformIfAlert(node: Blockquote): void {
  const firstChild = node.children[0];
  if (!firstChild || firstChild.type !== "paragraph") return;
  const paragraph = firstChild as Paragraph;
  const firstInline = paragraph.children[0];
  if (!firstInline || firstInline.type !== "text") return;
  const text = firstInline as Text;
  const match = ALERT_RE.exec(text.value);
  if (!match) return;

  const matched = match[1];
  if (!matched) return;
  const type = matched.toLowerCase() as AlertType;

  // Strip the marker from the rendered text.
  text.value = text.value.replace(ALERT_RE, "");
  // If the first inline became empty, drop it so the paragraph doesn't render
  // an empty leading line.
  if (text.value === "" && paragraph.children.length > 1) {
    paragraph.children.shift();
  }
  // Annotate so mdast-util-to-hast emits <aside> with the data attribute.
  node.data = {
    ...node.data,
    hName: "aside",
    hProperties: {
      ...((node.data as { hProperties?: Record<string, unknown> })?.hProperties ?? {}),
      className: ["theo-slide-alert"],
      "data-theo-slide-alert-type": type,
    },
  };
}

/**
 * Marpit-style `![bg](url)` background syntax detector.
 *
 * Marpit popularised the convention of declaring a slide background via a
 * standalone image whose alt-text starts with `bg`:
 *
 *     ![bg](https://example.com/photo.jpg)
 *     ![bg cover](url)   ![bg fit](url)   ![bg left](url)   ![bg right](url)
 *
 * LLMs trained on Marp output emit this naturally, so the slide primitive
 * adopts the same surface — but in a STRICTLY safe way:
 *
 * 1. Only triggers when the paragraph contains a SINGLE image (avoids
 *    collisions with inline images mixed with text).
 * 2. First-bg-wins (multiple `![bg]` directives in one slide → only the first
 *    is honoured; the others are also dropped from the tree to prevent
 *    duplicate rendering).
 * 3. The extracted result goes into `ParsedSlide.extractedBackground` (D18 /
 *    EC-5) and the Slide component prefers an explicit `frontmatter.backgroundImage`
 *    over the Marpit extraction.
 * 4. URL sanitization happens at the caller (`parseSlide`) via `sanitizeBgUrl`.
 */
import type { Image, Paragraph, Root } from "mdast";

const BG_ALT_RE = /^bg(?:\s+(\w+))?/i;

const VALID_MODIFIERS = new Set(["cover", "fit", "left", "right"]);

export interface ExtractedMarpitBackground {
  url: string;
  modifier?: "cover" | "fit" | "left" | "right";
}

/**
 * Walk the mdast tree, extract the first `![bg](url)` directive, drop ALL
 * matching paragraphs from the tree. Returns a new tree (children array
 * is filtered; node identities are preserved otherwise).
 */
export function extractMarpitBackgrounds(tree: Root): {
  tree: Root;
  background?: ExtractedMarpitBackground;
} {
  let background: ExtractedMarpitBackground | undefined;
  const filteredChildren = tree.children.filter((node) => {
    if (node.type !== "paragraph") return true;
    const p = node as Paragraph;
    // Single-child guard: paragraphs with mixed content (text + image) are
    // kept as-is — only "image-only" paragraphs are candidates.
    if (p.children.length !== 1) return true;
    const child = p.children[0];
    if (!child || child.type !== "image") return true;
    const img = child as Image;
    const match = BG_ALT_RE.exec(img.alt ?? "");
    if (!match) return true;
    // Capture once; drop subsequent bg paragraphs to avoid duplicate output.
    if (!background) {
      const modifierRaw = match[1]?.toLowerCase();
      const modifier =
        modifierRaw && VALID_MODIFIERS.has(modifierRaw)
          ? (modifierRaw as "cover" | "fit" | "left" | "right")
          : undefined;
      background = {
        url: img.url,
        modifier,
      };
    }
    return false; // drop this paragraph from the tree
  });
  return {
    tree: { ...tree, children: filteredChildren },
    background,
  };
}

/**
 * Slide plugin contract — extension points for rich-content engines.
 *
 * Plugins are composable transformers applied during `parseSlide`. Each plugin
 * may inspect/mutate the mdast tree (before HTML conversion), the hast tree
 * (after HTML conversion, before sanitize), and override React component
 * renderers (after sanitize). They may also declare sanitize-schema extensions
 * so custom tags (e.g. Shiki spans, KaTeX MathML, Mermaid SVG) survive the
 * security barrier.
 *
 * Design rules (ADRs in `wiki/rfcs/0004-slide-rich-content.md`):
 *   D1  — explicit `plugins` prop (no auto-detect).
 *   D2  — plugin shape: { name, mdastTransform?, hastTransform?, components? }.
 *   D13 — execution order: mdast → hast → sanitize (with merged extensions) → components.
 *   D16 — plugin error isolation: each plugin call is try/catch wrapped; errors
 *         are collected, not thrown.
 *   D17 — sanitize-schema merge is OBLIGATORY for plugins emitting non-default
 *         tags; without it, the sanitize step silently strips the content.
 *
 * Sanitize is the security barrier. Plugins NEVER bypass `hast-util-sanitize`.
 */
import type { Root as HastRoot } from "hast";
import type { Root as MdastRoot } from "mdast";
import type { FC } from "react";
import type { SlideValidationError } from "@/components/ui/slide/schema";

/** Sanitize schema extension declared by a plugin. Merged with `defaultSchema` in `parseSlide`. */
export interface SlideSanitizeExtension {
  /** Additional element tag names allowed past the sanitizer. */
  tagNames?: string[];
  /** Additional attribute allow-list keyed by tag name (or `"*"` for all tags). */
  attributes?: Record<string, string[]>;
}

/** A composable transformer + component-override unit. */
export interface SlidePlugin {
  /** Stable identifier used in PLUGIN_ERROR messages and dev logs. */
  name: string;
  /** Mutate the mdast tree before HTML conversion. Return value is forwarded. */
  mdastTransform?: (tree: MdastRoot) => Promise<MdastRoot> | MdastRoot;
  /** Mutate the hast tree after HTML conversion, before sanitize. */
  hastTransform?: (tree: HastRoot) => Promise<HastRoot> | HastRoot;
  /** React component overrides merged into the consumer's `components` map. */
  // biome-ignore lint/suspicious/noExplicitAny: third-party component override map
  components?: Record<string, FC<any>>;
  /** Sanitize-schema extension. Required for plugins emitting non-default tags. */
  sanitizeSchemaExtension?: SlideSanitizeExtension;
}

/** Merged sanitize-schema extensions from all plugins. */
export interface MergedSanitizeExtensions {
  tagNames: string[];
  attributes: Record<string, string[]>;
}

/** Composer over a plugin array. Hooks orchestrate transformation + error isolation. */
export interface PluginComposer {
  /** Run all `mdastTransform` hooks in array order. Collects errors. */
  runMdast(tree: MdastRoot, errors: SlideValidationError[]): Promise<MdastRoot>;
  /** Run all `hastTransform` hooks in array order. Collects errors. */
  runHast(tree: HastRoot, errors: SlideValidationError[]): Promise<HastRoot>;
  /** Merge all plugin component overrides; later-plugin-wins on conflict. */
  // biome-ignore lint/suspicious/noExplicitAny: third-party component override map
  mergedComponents(): Record<string, FC<any>>;
  /** Merge sanitize-schema extensions across all plugins (dedupes tag names). */
  mergedSanitizeExtensions(): MergedSanitizeExtensions;
}

/**
 * Build a composer over an array of plugins.
 *
 * Order semantics:
 *   - mdast transforms run sequentially in array order.
 *   - hast transforms run sequentially in array order.
 *   - components merge: later plugin wins on conflict (Object.assign semantics).
 *   - sanitize-schema extensions: union of tag names; union of attributes by tag.
 *
 * Error semantics (D16):
 *   - Each plugin call is wrapped in try/catch.
 *   - On throw, an error of code `PLUGIN_ERROR` is pushed to `errors[]` and the
 *     pipeline continues with the **non-transformed** input from that plugin
 *     (i.e. subsequent plugins see the tree that failed plugin received).
 *   - The composer NEVER throws; `parseSlide` keeps its "never throws on input"
 *     contract (RFC 0002 D9).
 */
export function composePlugins(plugins: SlidePlugin[]): PluginComposer {
  return {
    async runMdast(tree, errors) {
      let current = tree;
      for (const p of plugins) {
        if (!p.mdastTransform) continue;
        const previous = current;
        try {
          const result = await p.mdastTransform(current);
          if (!result || result.type !== "root") {
            // Defensive: a buggy plugin may return a non-Root node. Reject and
            // keep the previous tree so subsequent plugins see a valid input.
            throw new Error("mdastTransform returned non-Root node");
          }
          current = result;
        } catch (e) {
          current = previous;
          errors.push(makePluginError(p.name, "mdastTransform", e));
        }
      }
      return current;
    },
    async runHast(tree, errors) {
      let current = tree;
      for (const p of plugins) {
        if (!p.hastTransform) continue;
        const previous = current;
        try {
          const result = await p.hastTransform(current);
          if (!result || result.type !== "root") {
            throw new Error("hastTransform returned non-Root node");
          }
          current = result;
        } catch (e) {
          current = previous;
          errors.push(makePluginError(p.name, "hastTransform", e));
        }
      }
      return current;
    },
    mergedComponents() {
      // biome-ignore lint/suspicious/noExplicitAny: third-party component override map
      const out: Record<string, FC<any>> = {};
      for (const p of plugins) {
        if (p.components) Object.assign(out, p.components);
      }
      return out;
    },
    mergedSanitizeExtensions() {
      const tagNames = new Set<string>();
      const attributes: Record<string, Set<string>> = {};
      for (const p of plugins) {
        const ext = p.sanitizeSchemaExtension;
        if (!ext) continue;
        if (ext.tagNames) {
          for (const tag of ext.tagNames) tagNames.add(tag);
        }
        if (ext.attributes) {
          for (const [tag, attrs] of Object.entries(ext.attributes)) {
            if (!attributes[tag]) attributes[tag] = new Set();
            for (const a of attrs) attributes[tag].add(a);
          }
        }
      }
      const mergedAttrs: Record<string, string[]> = {};
      for (const [tag, set] of Object.entries(attributes)) {
        mergedAttrs[tag] = Array.from(set);
      }
      return {
        tagNames: Array.from(tagNames),
        attributes: mergedAttrs,
      };
    },
  };
}

function makePluginError(
  name: string,
  hook: "mdastTransform" | "hastTransform",
  e: unknown,
): SlideValidationError {
  const msg = e instanceof Error ? e.message : String(e);
  return {
    code: "PLUGIN_ERROR",
    path: [],
    message: `Plugin '${name}' failed in ${hook}: ${msg}`,
    got: name,
  };
}

/**
 * JSON Schema for the Slide YAML frontmatter — derived from the Zod
 * `slideFrontmatter` schema via Zod 4's native `z.toJSONSchema()`.
 *
 * Purpose: enable LLM-driven generation pipelines (OpenAI structured outputs,
 * Anthropic tool use, function calling, JSON-mode constrained generation) to
 * produce frontmatter that is GUARANTEED to pass `validateSlide` without
 * round-tripping through human-written prompt engineering.
 *
 * Usage (Anthropic tool use):
 *
 *     import { slideFrontmatterJsonSchema } from "@theokit/ui/slide";
 *
 *     const tool = {
 *       name: "render_slide",
 *       description: "Render a presentation slide.",
 *       input_schema: {
 *         type: "object",
 *         properties: {
 *           frontmatter: slideFrontmatterJsonSchema,
 *           body: { type: "string", description: "CommonMark + GFM markdown body" },
 *         },
 *         required: ["body"],
 *       },
 *     };
 *
 * The output matches Zod's behaviour exactly — anything that passes the JSON
 * Schema validator passes Zod, and vice-versa.
 *
 * Companion guide: `wiki/engines/slide-authoring-guide.md` — copy-paste system prompt that
 * documents every Tier 1 + Tier 2 feature with examples.
 */
import { z } from "zod";
import { slideFrontmatter } from "@/components/ui/slide/schema";

interface JsonSchemaProperties {
  [key: string]: Record<string, unknown>;
}

interface JsonSchemaWithProperties {
  properties?: JsonSchemaProperties;
  [key: string]: unknown;
}

/**
 * JSON Schema (Draft 2020-12) describing all accepted frontmatter fields:
 * `theme`, `layout`, `lang`, `color`, `backgroundColor`, `backgroundImage`,
 * `backgroundGradient`, `header`, `footer`, `paginate`.
 *
 * Note: `backgroundImage` uses a Zod `.transform()` (URL sanitization) which
 * cannot be represented in JSON Schema natively. We pass `unrepresentable: "any"`
 * to fall back to `{}` for transformed fields, then enrich `backgroundImage`
 * with manual metadata so LLMs still get useful constraints.
 *
 * Generated once at module load. Treat as immutable.
 */
const rawSchema = z.toJSONSchema(slideFrontmatter, {
  unrepresentable: "any",
}) as JsonSchemaWithProperties;

if (rawSchema.properties) {
  // Backgrounds carry hard constraints (http(s) only, ≤500_000 chars) that
  // Zod erases through `.transform()`. Inline them here so the LLM tooling
  // sees the same contract `sanitizeBgUrl` enforces at runtime.
  rawSchema.properties.backgroundImage = {
    type: "string",
    format: "uri",
    maxLength: 500_000,
    pattern: "^https?://",
    description:
      "Slide background image URL. Only http(s) schemes are accepted; data: URLs are rejected at runtime (use a hosted image).",
  };
}

export const slideFrontmatterJsonSchema = rawSchema;

/**
 * Container-fit hook for the Slide primitive.
 *
 * Observes the host element via `ResizeObserver` and computes a CSS scale
 * factor that fits the fixed logical canvas (default 1280×720) inside it,
 * preserving aspect ratio. Clamped to `[minScale, maxScale]`.
 *
 * Algorithm: `scale = clamp(min(W / canvasW, H / canvasH), min, max)`.
 *
 * Adapted from Reveal.js `transformSlides` (see reference doc §4.5 / §14.2).
 *
 * Cleanup: disconnects the observer on unmount or when deps change.
 */
import { type RefObject, useEffect, useState } from "react";

export interface UseSlideFitOptions {
  /** Lower clamp for scale. Default 0.1. */
  minScale?: number;
  /** Upper clamp for scale. Default 4. */
  maxScale?: number;
}

export function useSlideFit(
  ref: RefObject<HTMLElement | null>,
  canvasW: number,
  canvasH: number,
  opts: UseSlideFitOptions = {},
): number {
  const { minScale = 0.1, maxScale = 4 } = opts;
  const [scale, setScale] = useState(1);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    if (typeof ResizeObserver === "undefined") {
      // Test environments without ResizeObserver: do a one-shot measurement.
      const { width, height } = el.getBoundingClientRect();
      if (width > 0 && height > 0) {
        const raw = Math.min(width / canvasW, height / canvasH);
        setScale(Math.max(minScale, Math.min(raw, maxScale)));
      }
      return;
    }
    const update = (): void => {
      const { width, height } = el.getBoundingClientRect();
      if (width <= 0 || height <= 0) return;
      const raw = Math.min(width / canvasW, height / canvasH);
      const clamped = Math.max(minScale, Math.min(raw, maxScale));
      if (Number.isFinite(clamped)) setScale(clamped);
    };
    update();
    const ro = new ResizeObserver(update);
    ro.observe(el);
    return () => ro.disconnect();
  }, [ref, canvasW, canvasH, minScale, maxScale]);

  return scale;
}

